import{_ as t,o as a,c as n,a2 as i}from"./chunks/framework.CZo9GF0W.js";const u=JSON.parse(`{"title":"","description":"","frontmatter":{"layout":"home","hero":{"name":"Pitta","text":"A database client that lives in VS Code","tagline":"Browse and edit your data in a grid, or write a query. Both are first-class, and you never leave the editor.","image":{"src":"https://raw.githubusercontent.com/shresthadeepesh/pitta-db/main/packages/extension/resources/logo.png","alt":"Pitta"},"actions":[{"theme":"brand","text":"Get started","link":"/guide/getting-started"},{"theme":"alt","text":"Connection recipes","link":"/recipes/"},{"theme":"alt","text":"Write a driver","link":"/drivers/authoring"}]},"features":[{"title":"Six engines, one client","details":"PostgreSQL, MySQL/MariaDB, SQL Server, SQLite, MongoDB and Redis run on the same core, the same grid and the same guards. A driver is only called supported once it passes the conformance kit against a real server."},{"title":"Values stay exact","details":"numeric and int8 never pass through a JavaScript number — not on read, not on write, not on import. NULL and a missing field stay distinguishable all the way to the grid."},{"title":"Safe to point at production","details":"Tag a connection prod and destructive statements need the connection name typed back. Unqualified UPDATE and DELETE are refused by default, and read-only means read-only."},{"title":"Secrets in the keychain","details":"Passwords go to OS storage through VS Code's SecretStorage. The shareable connection file format cannot hold a password, so a committed profile is safe by construction."},{"title":"Real streaming","details":"Rows arrive from a server-side cursor with backpressure, so a million-row table opens as fast as a small one and exports stream to disk instead of into memory."},{"title":"Cancellation that cancels","details":"Cancel asks the server to stop — a PostgreSQL cancel request, a MongoDB killOp, a SQL Server attention packet — rather than abandoning the socket and leaving the query running."}]},"headers":[],"relativePath":"index.md","filePath":"index.md","lastUpdated":1789060268000}`),r={name:"index.md"};function s(o,e,d,c,h,l){return a(),n("div",null,[...e[0]||(e[0]=[i("",5)])])}const p=t(r,[["render",s]]);export{u as __pageData,p as default};
